class Solution:
    def kClosest(self, points: List[List[int]], k: int) -> List[List[int]]:
        # use heap datastructure
        heap = []
        for x, y in points:
            dis = (x**2 + y**2)**0.5
            heapq.heappush(heap, (-dis, [x, y]))
            if len(heap) > k:
                heapq.heappop(heap)

        return [p for _, p in heap]
